// src/lib/fhir/types.ts — the FHIR R4 subset this workspace emits (Phase 21;
// INTR-01).
//
// Deliberately a SUBSET: only the fields the clinical model actually carries.
// A hand-maintained structural type is not re-generated by a codegen step —
// the mapping is honest about being partial, and validation.ts checks what
// FHIR requires of each emitted resource (INTR-03).
//
// No DB types, no I/O: the mapping functions are pure projections of the
// existing record shapes (visits, medications, labs, imaging, allergies,
// patient observations) onto FHIR resources.

export type FhirCoding = { system?: string; code?: string; display?: string };

export type FhirCodeableConcept = {
  coding?: FhirCoding[];
  text?: string;
};

export type FhirReference = {
  reference: string;
  display?: string;
};

export type FhirPeriod = {
  start?: string;
  end?: string;
};

export type FhirAnnotation = {
  text: string;
  time?: string;
  authorString?: string;
};

export type FhirMeta = {
  /** The record's provenance travels WITH the resource (never lost). */
  source?: string;
  tag?: FhirCoding[];
  lastUpdated?: string;
};

export type FhirPatient = {
  resourceType: 'Patient';
  id: string;
  meta?: FhirMeta;
  identifier?: Array<{ system?: string; value: string }>;
  name?: Array<{ family?: string; given?: string[] }>;
  gender?: 'male' | 'female' | 'other' | 'unknown';
  birthDate?: string;
};

export type FhirEncounter = {
  resourceType: 'Encounter';
  id: string;
  meta?: FhirMeta;
  status: 'planned' | 'arrived' | 'in-progress' | 'finished' | 'cancelled';
  class?: { system?: string; code?: string; display?: string };
  type?: FhirCodeableConcept[];
  subject: FhirReference;
  period?: FhirPeriod;
  reasonCode?: FhirCodeableConcept[];
  hospitalization?: { dischargeDisposition?: FhirCodeableConcept };
};

export type FhirMedicationRequest = {
  resourceType: 'MedicationRequest';
  id: string;
  meta?: FhirMeta;
  status: 'active' | 'on-hold' | 'stopped' | 'cancelled';
  intent: 'order';
  subject: FhirReference;
  medicationCodeableConcept?: FhirCodeableConcept;
  authoredOn?: string;
  dosageInstruction?: Array<{ text?: string; route?: FhirCodeableConcept; timing?: { code?: FhirCodeableConcept } }>;
  note?: FhirAnnotation[];
};

export type FhirObservation = {
  resourceType: 'Observation';
  id: string;
  meta?: FhirMeta;
  status: 'final' | 'amended' | 'entered-in-error';
  category?: FhirCodeableConcept[];
  code: FhirCodeableConcept;
  subject: FhirReference;
  effectiveDateTime?: string;
  valueQuantity?: { value: number; unit?: string; system?: string; code?: string };
  valueString?: string;
  interpretation?: FhirCodeableConcept[];
  referenceRange?: Array<{ text?: string }>;
  note?: FhirAnnotation[];
};

export type FhirDiagnosticReport = {
  resourceType: 'DiagnosticReport';
  id: string;
  meta?: FhirMeta;
  status: 'final' | 'amended' | 'entered-in-error';
  category?: FhirCodeableConcept[];
  code: FhirCodeableConcept;
  subject: FhirReference;
  effectiveDateTime?: string;
  conclusion?: string;
  presentedForm?: Array<{ contentType?: string; url?: string; title?: string }>;
};

export type FhirAllergyIntolerance = {
  resourceType: 'AllergyIntolerance';
  id: string;
  meta?: FhirMeta;
  clinicalStatus?: { coding?: FhirCoding[] };
  verificationStatus?: { coding?: FhirCoding[] };
  type?: 'allergy' | 'intolerance';
  category?: 'food' | 'medication' | 'environment' | 'biologic';
  criticality?: 'low' | 'high' | 'unable-to-assess';
  code?: FhirCodeableConcept;
  patient: FhirReference;
  recordedDate?: string;
  reaction?: Array<{ manifestation: FhirCodeableConcept[]; severity?: string }>;
  note?: FhirAnnotation[];
};

export type FhirBundleEntry = {
  fullUrl: string;
  resource:
    | FhirPatient
    | FhirEncounter
    | FhirMedicationRequest
    | FhirObservation
    | FhirDiagnosticReport
    | FhirAllergyIntolerance;
};

export type FhirBundle = {
  resourceType: 'Bundle';
  type: 'collection';
  timestamp?: string;
  entry: FhirBundleEntry[];
};

/** Every resource type the mapping can emit (the closed set, INTR-01). */
export const FHIR_RESOURCE_TYPES = [
  'Patient',
  'Encounter',
  'MedicationRequest',
  'Observation',
  'DiagnosticReport',
  'AllergyIntolerance',
] as const satisfies readonly FhirBundleEntry['resource']['resourceType'][];

/** The stable fullUrl prefix for this workspace's projections. */
export const FHIR_URL_PREFIX = 'urn:uuid:';
